$('#sequenceBars').onchange=()=>resizeSequence(Math.max(1,Math.min(128,Number($('#sequenceBars').value)||1)));
$('#previousBar').onclick=()=>{sequencePage=Math.max(0,sequencePage-1);renderSteps()};
$('#nextBar').onclick=()=>{sequencePage=Math.min(sequenceBars[currentPattern]-1,sequencePage+1);renderSteps()};
$('#doubleSequence').onclick=()=>{if(sequenceBars[currentPattern]>=128){status('Longueur maximale : 128 mesures.');return}resizeSequence(Math.min(128,sequenceBars[currentPattern]*2),true)};
$('#halfSequence').onclick=()=>resizeSequence(Math.max(1,Math.floor(sequenceBars[currentPattern]/2)));
